}

function buildHelp(programName) {
  return `${buildUsage(programName)}\noptions:\n  -h, --help  show this help message and exit\n  --a A\n`;
}

function buildError(programName, message) {
  return `${buildUsage(programName)}${programName}: error: ${message}\n`;
}

export function getProgramName(processArgv) {
  const scriptPath = processArgv[1] ?? 'test3.mjs';
  const normalizedPath = scriptPath.replaceAll('\\', '/');
  const lastSlashIndex = normalizedPath.lastIndexOf('/');
  return lastSlashIndex >= 0
    ? normalizedPath.slice(lastSlashIndex + 1)
    : normalizedPath;
}

export function parseCommandLine(argv, programName) {
  if (argv.includes('-h') || argv.includes('--help')) {
    return {
      kind: 'help',
      text: buildHelp(programName),
      exitCode: 0,
    };
  }

  let hasA = false;
  let aValue = 0;
  const unknownArguments = [];

  for (let index = 0; index < argv.length; index += 1) {
