      const valueToken = argv[index + 1];

      if (
        valueToken === undefined ||
        valueToken === '--' ||
        (valueToken.startsWith('-') &&
          !NEGATIVE_NUMBER_OPTION_VALUE_PATTERN.test(valueToken))
      ) {
        return {
          kind: 'error',
          text: buildError(programName, 'argument --a: expected one argument'),
          exitCode: 2,
        };
      }

      const parsedValue = parsePythonFloatToken(valueToken);

      if (parsedValue === null) {
        return {
          kind: 'error',
