            programName,
            `argument --a: invalid float value: '${valueToken}'`,
          ),
          exitCode: 2,
        };
      }

      hasA = true;
      aValue = parsedValue;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      const valueToken = token.slice(4);
      const parsedValue = parsePythonFloatToken(valueToken);

      if (parsedValue === null) {
        return {
          kind: 'error',
          text: buildError(
            programName,
            `argument --a: invalid float value: '${valueToken}'`,
          ),
          exitCode: 2,
        };
      }

      hasA = true;
      aValue = parsedValue;
      continue;
    }

    unknownArguments.push(token);
  }

  if (!hasA) {
    return {
      kind: 'error',
      text: buildError(
        programName,
        'the following arguments are required: --a',
      ),
      exitCode: 2,
    };
